* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

html, body {
    height: 100%;
}

body {
    background-color: var(--color-bg-primary);
    color: var(--color-text-primary);
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Roboto', 'Oxygen', 'Ubuntu', 'Cantarell', sans-serif;
    font-size: 14px;
    line-height: 1.6;
}

.container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 32px 20px;
    min-height: 100vh;
}

header {
    margin-bottom: 40px;
}

header h1 {
    font-size: 28px;
    font-weight: 600;
    letter-spacing: -0.5px;
}

main {
    display: flex;
    justify-content: center;
}

.image-preview-section {
    width: 100%;
    max-width: 500px;
}

.image-card {
    background-color: var(--color-bg-secondary);
    border: 1px solid var(--color-border);
    border-radius: 12px;
    overflow: hidden;
    transition: all var(--transition-smooth);
    box-shadow: 0 4px 16px var(--color-shadow);
}

.image-card:hover {
    border-color: var(--color-accent);
    box-shadow: 0 8px 24px rgba(91, 158, 255, 0.15);
}

.image-wrapper {
    width: 100%;
    aspect-ratio: 1;
    background-color: var(--color-bg-tertiary);
    display: flex;
    align-items: center;
    justify-content: center;
    overflow: hidden;
}

.image-wrapper img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform var(--transition-smooth);
}

.image-card:hover .image-wrapper img {
    transform: scale(1.05);
}

.image-info {
    padding: 20px;
    border-bottom: 1px solid var(--color-border);
}

.image-info h3 {
    font-size: 16px;
    font-weight: 600;
    margin-bottom: 8px;
}

.image-date {
    font-size: 13px;
    color: var(--color-text-secondary);
}

.delete-btn {
    width: 100%;
    padding: 12px 20px;
    background-color: transparent;
    border: none;
    color: var(--color-danger);
    font-size: 14px;
    font-weight: 500;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    transition: all var(--transition-smooth);
}

.delete-btn:hover {
    background-color: rgba(255, 87, 87, 0.08);
    color: var(--color-danger-hover);
}

.delete-btn:active {
    background-color: rgba(255, 87, 87, 0.12);
}

.delete-btn .icon {
    font-size: 16px;
}

/* Modal Styles */
.modal-overlay {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background-color: rgba(0, 0, 0, 0.6);
    display: flex;
    align-items: center;
    justify-content: center;
    backdrop-filter: blur(2px);
    z-index: 1000;
    opacity: 0;
    visibility: hidden;
    transition: opacity var(--transition-smooth), visibility var(--transition-smooth);
    padding: 20px;
}

.modal-overlay:not([hidden]) {
    opacity: 1;
    visibility: visible;
}

.modal-dialog {
    background-color: var(--color-bg-secondary);
    border: 1px solid var(--color-border);
    border-radius: 12px;
    box-shadow: 0 20px 60px var(--color-shadow);
    width: 100%;
    max-width: 420px;
    animation: slideUp var(--transition-smooth) ease-out;
}

@keyframes slideUp {
    from {
        opacity: 0;
        transform: translateY(16px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

.modal-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 24px;
    border-bottom: 1px solid var(--color-border);
}

.modal-header h2 {
    font-size: 18px;
    font-weight: 600;
    margin: 0;
}

.modal-close {
    background: none;
    border: none;
    color: var(--color-text-secondary);
    font-size: 24px;
    cursor: pointer;
    width: 32px;
    height: 32px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 6px;
    transition: all var(--transition-smooth);
}

.modal-close:hover {
    background-color: var(--color-bg-tertiary);
    color: var(--color-text-primary);
}

.modal-body {
    padding: 24px;
    color: var(--color-text-secondary);
    font-size: 14px;
    line-height: 1.6;
}

.modal-body p {
    margin: 0;
}

.modal-footer {
    display: flex;
    gap: 12px;
    padding: 24px;
    border-top: 1px solid var(--color-border);
    justify-content: flex-end;
}

.modal-btn {
    padding: 10px 20px;
    border: none;
    border-radius: 6px;
    font-size: 14px;
    font-weight: 500;
    cursor: pointer;
    transition: all var(--transition-smooth);
    min-width: 100px;
}

.modal-btn--cancel {
    background-color: transparent;
    color: var(--color-text-primary);
    border: 1px solid var(--color-border);
}

.modal-btn--cancel:hover {
    background-color: var(--color-bg-tertiary);
    border-color: var(--color-text-secondary);
}

.modal-btn--delete {
    background-color: var(--color-danger);
    color: white;
}

.modal-btn--delete:hover {
    background-color: var(--color-danger-hover);
}

.modal-btn--delete:active {
    transform: scale(0.98);
}

/* Responsive Design */
@media (max-width: 640px) {
    .container {
        padding: 20px 16px;
    }

    header h1 {
        font-size: 24px;
    }

    .modal-dialog {
        max-width: 100%;
    }

    .modal-footer {
        flex-direction: column-reverse;
    }

    .modal-btn {
        width: 100%;
    }
}
