/**
 * Modal Dialog Controller
 * Manages opening and closing of the delete confirmation modal
 */

class ModalController {
    constructor() {
        this.modal = document.getElementById('deleteModal');
        this.triggers = document.querySelectorAll('.trigger');
        this.closeBtn = this.modal.querySelector('.modal-close');
        this.cancelBtn = this.modal.querySelector('.modal-btn--cancel');
        this.deleteBtn = this.modal.querySelector('.modal-btn--delete');

        this.initializeListeners();
    }

    initializeListeners() {
        // Open modal when delete button is clicked
        this.triggers.forEach(trigger => {
            trigger.addEventListener('click', () => this.openModal());
        });

        // Close modal with close button
        this.closeBtn.addEventListener('click', () => this.closeModal());

        // Close modal with cancel button
        this.cancelBtn.addEventListener('click', () => this.closeModal());

        // Handle delete confirmation
        this.deleteBtn.addEventListener('click', () => this.handleDelete());

        // Close modal when clicking outside of it
        this.modal.addEventListener('click', (e) => {
            if (e.target === this.modal) {
                this.closeModal();
            }
        });

        // Close modal on Escape key
        document.addEventListener('keydown', (e) => {
            if (e.key === 'Escape' && !this.modal.hidden) {
                this.closeModal();
            }
        });
    }

    openModal() {
        this.modal.removeAttribute('hidden');
        // Prevent body scroll when modal is open
        document.body.style.overflow = 'hidden';
    }

    closeModal() {
        this.modal.setAttribute('hidden', '');
        // Restore body scroll
        document.body.style.overflow = '';
    }

    handleDelete() {
        // Simulate deletion (in a real app, this would make an API call)
        console.log('Image deleted successfully');
        alert('Image has been deleted from your library');
        this.closeModal();
    }
}

// Initialize modal controller when DOM is ready
document.addEventListener('DOMContentLoaded', () => {
    new ModalController();
});

